insert into public.projects (position,published,translations) values (0,true,'{"pt-BR":{"name":"Portfólio pessoal","author":"Paulo Vieira","mark":"PV","category":"Aplicação web","summary":"Uma experiência para apresentar meu trabalho, com navegação acessível, dois idiomas e uma cena espacial interativa.","technologies":["Angular 21","TypeScript","Material","Motion"],"collectionStack":"Angular / TypeScript","demoRoute":"/","demoLabel":"Explorar o portfólio","detailsTitle":"Por dentro do portfólio","details":[{"title":"Uma base consistente","description":"Componentes Angular, tema Material personalizado e layouts que se adaptam do celular ao desktop."},{"title":"Movimento com intenção","description":"Planeta em camadas, estrelas e um foguete acionado pelo mouse. As animações respeitam a preferência por movimento reduzido."},{"title":"Duas formas de explorar","description":"Versões em português e inglês, com páginas pré-renderizadas e atenção à navegação por teclado."}]},"en-US":{"name":"Personal portfolio","author":"Paulo Vieira","mark":"PV","category":"Web application","summary":"An experience showcasing my work, with accessible navigation, two languages, and an interactive space scene.","technologies":["Angular 21","TypeScript","Material","Motion"],"collectionStack":"Angular / TypeScript","demoRoute":"/","demoLabel":"Explore the portfolio","detailsTitle":"Inside the portfolio","details":[{"title":"A consistent foundation","description":"Angular components, a custom Material theme, and layouts that adapt from mobile to desktop."},{"title":"Purposeful motion","description":"A layered planet, stars, and a mouse-triggered rocket. Animations respect reduced-motion preferences."},{"title":"Two ways to explore","description":"Portuguese and English versions, with prerendered pages and attention to keyboard navigation."}]}}'::jsonb);
insert into public.experiences (position,published,translations) values (0,true,'{"pt-BR":{"role":"Engenheiro de software","company":"Empresa exemplo A","period":"2025 até o momento","summary":"Exemplo de atuação na evolução de aplicações web e na definição de soluções técnicas.","highlights":["Construção de interfaces acessíveis e responsivas.","Colaboração em decisões de arquitetura e revisão de código."],"technologies":["Angular","TypeScript","Node.js"]},"en-US":{"role":"Software engineer","company":"Example company A","period":"2025 to present","summary":"Example work evolving web applications and defining technical solutions.","highlights":["Building accessible, responsive interfaces.","Contributing to architecture decisions and code reviews."],"technologies":["Angular","TypeScript","Node.js"]}}'::jsonb);
insert into public.experiences (position,published,translations) values (1,true,'{"pt-BR":{"role":"Desenvolvedor front-end","company":"Empresa exemplo B","period":"2023 a 2025","summary":"Exemplo de desenvolvimento de interfaces e integração com serviços de uma plataforma digital.","highlights":["Implementação de componentes reutilizáveis.","Integração com APIs e melhoria dos fluxos de navegação."],"technologies":["Angular","Sass","REST"]},"en-US":{"role":"Front-end developer","company":"Example company B","period":"2023 to 2025","summary":"Example interface development and service integration for a digital platform.","highlights":["Implementing reusable components.","Integrating APIs and improving navigation flows."],"technologies":["Angular","Sass","REST"]}}'::jsonb);
insert into public.experiences (position,published,translations) values (2,true,'{"pt-BR":{"role":"Desenvolvedor júnior","company":"Empresa exemplo C","period":"2021 a 2023","summary":"Exemplo de início de carreira com manutenção de aplicações e desenvolvimento acompanhado por uma equipe.","highlights":["Correção de problemas e entrega de pequenas funcionalidades.","Aprendizado de versionamento, testes e boas práticas."],"technologies":["JavaScript","HTML","CSS"]},"en-US":{"role":"Junior developer","company":"Example company C","period":"2021 to 2023","summary":"Example early-career work maintaining applications and developing alongside a team.","highlights":["Fixing issues and delivering small features.","Learning version control, testing, and best practices."],"technologies":["JavaScript","HTML","CSS"]}}'::jsonb);
insert into public.profiles (position,published,translations) values (0,true,'{"pt-BR":{"name":"Paulo Vieira","role":"Engenheiro de Software","description":"Gosto de transformar ideias em aplicações claras, úteis e bem construídas. Meu foco está em interfaces acessíveis, código organizado e experiências que funcionam bem em diferentes dispositivos.","descriptionMore":"Busco entender o problema antes de escolher a solução. Valorizo a troca com outras pessoas, o aprendizado contínuo e a atenção aos detalhes, da primeira interação à manutenção do produto.","principles":[{"title":"Clareza antes de complexidade","description":"Soluções simples de entender, usar e evoluir."},{"title":"Atenção a quem usa","description":"Acessibilidade e usabilidade fazem parte da construção."},{"title":"Construção em conjunto","description":"Escuta, documentação e colaboração para tomar boas decisões."}]},"en-US":{"name":"Paulo Vieira","role":"Software Engineer","description":"I enjoy turning ideas into clear, useful, well-built applications. I focus on accessible interfaces, organized code, and experiences that work well across devices.","descriptionMore":"I seek to understand the problem before choosing a solution. I value exchanging ideas, continuous learning, and attention to detail, from the first interaction to product maintenance.","principles":[{"title":"Clarity before complexity","description":"Solutions that are easy to understand, use, and evolve."},{"title":"Attention to the people using it","description":"Accessibility and usability are part of the building process."},{"title":"Building together","description":"Listening, documentation, and collaboration to make sound decisions."}]}}'::jsonb);
